package com.capstone.strayassist.core.animal.entity;

import jakarta.persistence.*;
import java.time.LocalDate;

/**
 * <p>Maps to the {@code animal_profile} table. Each row is one animal
 * tracked by the system (e.g. for reporting, rescue, feeding, or adoption).</p>
 */
@Entity
@Table(name = "animal_profile")
public class Animal {

  // Primary key; auto-generated by the database using an identity column
  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;

  // Animal's name; required
  @Column(nullable = false)
  private String name;

  // Animal's birth date; required. Used to derive the animal's age.
  @Column(nullable = false)
  private LocalDate birthDate;

  // Animal's sex; stored as a string (MALE/FEMALE/UNKNOWN). Required.
  @Enumerated(EnumType.STRING)
  @Column(nullable = false)
  private Sex sex;

  // Animal's type (DOG/CAT); stored as a string. Required.
  @Enumerated(EnumType.STRING)
  @Column(nullable = false)
  private AnimalType type;

  // Where the animal was found / is currently located; required
  @Column(nullable = false)
  private String location;

  // Animal's weight in kilograms; required
  @Column(nullable = false)
  private Double weight;

  // Allowed values for an animal's sex
  public enum Sex { MALE, FEMALE, UNKNOWN }

  // Allowed values for an animal's type
  public enum AnimalType { DOG, CAT }

  // ---- Getters ----

  // Returns the generated primary key
  public Long getId() {
    return id;
  }

  // Returns the animal's name
  public String getName() {
    return name;
  }

  // Returns the animal's birth date
  public LocalDate getBirthDate() {
    return birthDate;
  }

  // Returns the animal's sex
  public Sex getSex() {
    return sex;
  }

  // Returns the animal's type (renamed from getAnimalType for consistency)
  public AnimalType getType() {
    return type;
  }

  // Returns the animal's location
  public String getLocation() {
    return location;
  }

  // Returns the animal's weight in kg
  public Double getWeight() {
    return weight;
  }

  // ---- Setters ----

  // Sets the primary key (usually managed by JPA, exposed for tests/mappers)
  public void setId(Long id) {
    this.id = id;
  }

  // Sets the animal's name
  public void setName(String name) {
    this.name = name;
  }

  // Sets the animal's birth date
  public void setBirthDate(LocalDate birthDate) {
    this.birthDate = birthDate;
  }

  // Sets the animal's sex
  public void setSex(Sex sex) {
    this.sex = sex;
  }

  // Sets the animal's type
  public void setType(AnimalType type) {
    this.type = type;
  }

  // Sets the animal's location
  public void setLocation(String location) {
    this.location = location;
  }

  // Sets the animal's weight in kg
  public void setWeight(Double weight) {
    this.weight = weight;
  }
}
